import React, { useEffect, useState } from 'react';
import type { Feature } from '../../router/routes';

// Dashboard feature: a home screen summarising the whole account — how many clients and projects
// there are, how much money is still owed (the total of every UNPAID invoice across all projects),
// and how many SENT invoices are overdue (past their due date). Read-only; owns its own state and
// reads its own /api/dashboard endpoint.
type Summary = {
  clientsCount: number;
  projectsCount: number;
  outstandingTotal: number;
  overdueCount: number;
};

function money(amount: number): string {
  return `$${Number(amount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function DashboardPage() {
  const [summary, setSummary] = useState<Summary | null>(null);

  useEffect(() => {
    async function load() {
      const res = await fetch('/api/dashboard');
      setSummary(await res.json());
    }
    void load();
  }, []);

  if (!summary) {
    return <section data-testid="dashboard" />;
  }

  // One tile per headline figure. Listing them as data keeps the markup to a single repeated block
  // and puts every tile's label and value in one place to read (and relabel) at a glance.
  const tiles = [
    { testid: 'dashboard-clients', label: 'Clients', valueTestid: 'dashboard-clients-count', value: summary.clientsCount },
    { testid: 'dashboard-projects', label: 'Jobs', valueTestid: 'dashboard-projects-count', value: summary.projectsCount },
    { testid: 'dashboard-outstanding', label: 'Outstanding', valueTestid: 'dashboard-outstanding-total', value: money(summary.outstandingTotal) },
    { testid: 'dashboard-overdue', label: 'Overdue invoices', valueTestid: 'dashboard-overdue-count', value: summary.overdueCount },
  ];

  return (
    <section data-testid="dashboard">
      {tiles.map((tile) => (
        <div key={tile.testid} data-testid={tile.testid}>
          <span>{tile.label}</span>
          <span data-testid={tile.valueTestid}>{tile.value}</span>
        </div>
      ))}
    </section>
  );
}

export const feature: Feature = { id: 'dashboard', label: 'Dashboard', Page: DashboardPage };
===ROUTES===
// Manifest-based routing (shared surface). A feature is a NEW file at features/<name>/feature.tsx
// that exports a `feature: Feature`; it is discovered here via import.meta.glob, so adding a page is
// a new file — never an edit to this router (DESIGN.md §8).
import type { ComponentType } from 'react';

export type Feature = {
  id: string; // section id -> nav-<id> data-testid
  label: string; // nav link text
  Page: ComponentType;
};

const modules = import.meta.glob<{ feature: Feature }>('../features/*/feature.tsx', { eager: true });

export const features: Feature[] = Object.values(modules)
  .map((m) => m.feature)
  .filter((f): f is Feature => Boolean(f))
  .sort((a, b) => a.label.localeCompare(b.label));
===MAIN===
import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';
import { features } from './router/routes';
import { GlobalSearch } from './search/GlobalSearch';

// Minimal base shell. Features register additively via the manifest router (router/routes.ts); the
// shell renders a nav link per feature and the active feature's page. Navigation is via nav-* clicks
// (no URL router needed for the specs). Every observable element carries a stable data-testid.
function App() {
  const [active, setActive] = useState<string | null>(null);
  const current = features.find((f) => f.id === active);
  return (
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        {features.map((f) => (
          <button key={f.id} data-testid={`nav-${f.id}`} onClick={() => setActive(f.id)}>
            {f.label}
          </button>
        ))}
      </nav>
      <GlobalSearch />
      <main data-testid="app-home">{current ? <current.Page /> : null}</main>
    </div>
  );
}

createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

